import json
members = {}
for line in open('members.csv').read().strip().splitlines()[1:]:
    m,w,s = line.split(',')
    members[m] = (int(w), s)

ballots = [json.loads(l) for l in open('ballots.jsonl') if l.strip()]

# active members only, highest seq ballot per (motion, member)
active = {m for m,(w,s) in members.items() if s=='active'}
from collections import defaultdict
latest = {}
for b in ballots:
    key = (b['motion'], b['member'])
    if key not in latest or b['seq'] > latest[key]['seq']:
        latest[key] = b

motions = {}
for key, b in latest.items():
    motion, member = key
    if member not in active:
        continue
    w = members[member][0]
    motions.setdefault(motion, {'yes':0,'no':0})
    motions[motion][b['vote']] += w

print(motions)
for m, s in sorted(motions.items()):
    passed = s['yes'] >= 4 and s['yes'] > s['no']
    print(m, s, 'pass' if passed else 'fail')

